package com.moviebooking.notification.config;
import org.apache.kafka.common.TopicPartition;import org.springframework.context.annotation.*;import org.springframework.kafka.config.*;import org.springframework.kafka.core.ConsumerFactory;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.kafka.listener.*;import org.springframework.util.backoff.FixedBackOff;
@Configuration public class KafkaConfig {@Bean ConcurrentKafkaListenerContainerFactory<String,String> kafkaListenerContainerFactory(ConsumerFactory<String,String> consumerFactory,KafkaTemplate<Object,Object> template){ConcurrentKafkaListenerContainerFactory<String,String> f=new ConcurrentKafkaListenerContainerFactory<>();f.setConsumerFactory(consumerFactory);DeadLetterPublishingRecoverer recoverer=new DeadLetterPublishingRecoverer(template,(record,ex)->new TopicPartition(record.topic()+".DLT",record.partition()));f.setCommonErrorHandler(new DefaultErrorHandler(recoverer,new FixedBackOff(1000L,2L)));return f;}}
